if (!URL || !KEY) throw new Error('APPSYNC_URL and APPSYNC_API_KEY must be set');
const res = await fetch(URL, { /* ... */ });
if (!res.ok) throw new Error(`AppSync HTTP ${res.status}: ${await res.text()}`);
