cp-express-003.example:
```js
app.get('/products/:id', async (req, res, next) => {
  try {
    const product = await getProduct(req.params.id);
    res.status(product ? 200 : 404).send(productPage(product)); // null -> 404
  } catch (err) {
    next(err); // real failure -> 500 handler
  }
});
```

